using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SeaRequiemCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/SeaRequiemCustomDescription", order = 0)]
public class SeaRequiemCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		SeaRequiemAction seaRequiemAction = battleAction as SeaRequiemAction;
		return Smart.Format(GetRawLocalizedDescription(battleAction), GetAmountWithUnlockablesModification(amountModified), seaRequiemAction.SeaRequiemIncreaseAmount);
	}
}
